<?php require_once __DIR__.'/../includes/functions.php';$adminTitle='التحليلات';$sales=db()->query('SELECT DATE(created_at) d,COUNT(*) orders,COALESCE(SUM(total),0) revenue FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY DATE(created_at) ORDER BY d')->fetchAll();$top=db()->query('SELECT name,sales_count,stock FROM products ORDER BY sales_count DESC LIMIT 8')->fetchAll();include 'header.php';?><div class="cards"><div class="stat"><span>إيرادات آخر 30 يوماً</span><b><?=money((float)db()->query('SELECT COALESCE(SUM(total),0) FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 30 DAY)')->fetchColumn())?></b></div><div class="stat"><span>معدل التحويل التقريبي</span><b>—</b></div><div class="stat"><span>رسائل جديدة</span><b><?=db()->query('SELECT COUNT(*) FROM contact_messages WHERE status="new"')->fetchColumn()?></b></div><div class="stat"><span>مخزون منخفض</span><b><?=db()->query('SELECT COUNT(*) FROM products WHERE stock<5')->fetchColumn()?></b></div></div><div class="panel"><h2>المبيعات اليومية</h2><table class="table"><tr><th>التاريخ</th><th>الطلبات</th><th>الإيراد</th></tr><?php foreach($sales as $s):?><tr><td><?=$s['d']?></td><td><?=$s['orders']?></td><td><?=money($s['revenue'])?></td></tr><?php endforeach;?></table></div><div class="panel"><h2>الأكثر مبيعاً</h2><table class="table"><?php foreach($top as $p):?><tr><td><?=e($p['name'])?></td><td><?=$p['sales_count']?> مبيعات</td><td><?=$p['stock']?> بالمخزون</td></tr><?php endforeach;?></table></div><?php include 'footer.php';?>
